oxy_webhelp_navlinks = {"ir_excess_obj_del_clean_rec-d39536e57254":{"topics":[{"title":"Supported object types for deletion","shortdesc":"<p class=\"shortdesc\">Clean recovery deletes a defined set of Microsoft Entra ID object types present         in the live tenant but absent from the snapshot. <span class=\"ph\">RSC<\/span> restores object         types not in the supported set without deleting excess objects of that         type.<\/p>","href":"identity_resilience\/ir_excess_obj_del_obj_types.html","attributes":{"data-id":"ir_excess_obj_del_obj_types"},"menu":{"hasChildren":false},"tocID":"ir_excess_obj_del_obj_types-d39536e57268","topics":[]},{"title":"Recovery summary for clean recovery","shortdesc":"<p class=\"shortdesc\">The recovery summary for clean recovery includes updated object counts, a new         deletion details file, and result statuses that reflect the outcome of excess object         deletion.<\/p>","href":"identity_resilience\/ir_clean_rec_recovery_summ.html","attributes":{"data-id":"ir_clean_rec_recovery_summ"},"menu":{"hasChildren":false},"tocID":"ir_clean_rec_recovery_summ-d39536e57282","topics":[]}]}};